{
    "id": "https://raw.githubusercontent.com/rolfvreijdenberger/jsend-json-schema/master/jsend-json-schema.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "jsend json schema",
    "description": "This is a json-schema for the jsend format for json responses for applications. see https://labs.omniti.com/labs/jsend/wiki",
    "type": "object",
    "oneOf": [
        {
            "$ref": "#/definitions/success"
        },
        {
            "$ref": "#/definitions/fail"
        },
        {
            "$ref": "#/definitions/error"
        }
    ],
    "definitions": {
        "success": {
            "description": "All went well, and (usually) some data was returned.",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^success$",
                    "description": "the status for a succesful handling"
                },
                "data": {
                    "description": "Acts as the wrapper for any data returned by the API call. If the call returns no data (as in the last example), data should be set to null.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "fail": {
            "description": "There was a problem with the data submitted, or some pre-condition of the API call wasn't satisfied",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^fail$",
                    "description": "the status for a failure handling"
                },
                "data": {
                    "description": "provides the wrapper for the details of why the request failed. If the reasons for failure correspond to POST values, the response object's keys SHOULD correspond to those POST values.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "error": {
            "description": "An error occurred in processing the request, i.e. an exception was thrown",
            "required": [
                "status",
                "message"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^error$",
                    "description": "the status for a error handling"
                },
                "message": {
                    "$ref": "#/definitions/message"
                },
                "code": {
                    "$ref": "#/definitions/code"
                },
                "data": {
                    "description": "A generic container for any other information about the error, i.e. the conditions that caused the error, stack traces, etc.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "data": {
            "description": "a generic container for data returned for success, fail or error",
            "type": [
                "string",
                "null",
                "array",
                "object",
                "integer",
                "boolean"
            ]
        },
        "code": {
            "description": "A numeric code corresponding to the error in an error result, if applicable",
            "type": [
                "string",
                "integer"
            ]
        },
        "message": {
            "description": "A meaningful, end-user-readable (or at the least log-worthy) message, explaining what went wrong in an error result.",
            "type": "string"
        }
    }
}

{
    "title": "server info",
    "$schema": "http://json-schema.org/draft-06/schema#",
    "type": "object",
    "additionalProperties": false,
    "properties": {
        "fabric_fq_name": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "ipmi": {
            "$id": "/properties/ipmi",
            "type": "object",
            "required": [
                "ipmi_subnet_list",
                "ipmi_credentials"
            ],
            "properties": {
                "ipmi_subnet_list": {
                    "$id": "/properties/ipmi/properties/ipmi_subnet_list",
                    "type": "array",
                    "items": {
                        "$id": "/properties/ipmi/properties/ipmi_subnet_list/items",
                        "type": "string",
                        "description": "List of the subnet prefixes that could be carved out for the p2p networks between fabric devices.",
                        "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
                    }
                },
                "ipmi_credentials": {
                    "$id": "/properties/ipmi/properties/ipmi_credentials",
                    "type": "array",
                    "items": {
                        "$id": "/properties/ipmi/properties/ipmi_credentials/items",
                        "description": "The IPMI user:password credentials",
                        "type": "string"
                    }
                },
                "ipmi_port_ranges": {
                    "$id": "/properties/ipmi/properties/ipmi_port_ranges",
                    "type": "array",
                    "items": {
                        "$id": "/properties/ipmi/properties/ipmi_credentials/items",
                        "type": "object",
                        "required": [
                            "port_range_start",
                            "port_range_end"
                        ],
                        "properties": {
                            "port_range_start": {
                                "$id": "/properties/ipmi/properties/ipmi_port_ranges/items/port_range_start",
                                "description": "Start of IPMI Port Range",
                                "type": "integer"
                            },
                            "port_range_end": {
                                "$id": "/properties/ipmi/properties/ipmi_port_ranges/items/port_range_end",
                                "description": "End of IPMI Port Range",
                                "type": "integer"
                            }
                        }
                    }
                }
            }
        },
        "ironic": {
            "$id": "/properties/ironic",
            "type": "object",
            "required": [
                "auth_url",
                "username",
                "password"
            ],
            "properties": {
                "auth_url": {
                    "$id": "/properties/ironic/properties/auth_url",
                    "description": "The Ironic Auth URL",
                    "type": "string"
                },
                "username": {
                    "$id": "/properties/ironic/properties/username",
                    "description": "The Ironic Auth username",
                    "type": "string"
                },
                "password": {
                    "$id": "/properties/ironic/properties/password",
                    "description": "The Ironic Auth password",
                    "type": "string"
                },
                "introspection_flag": {
                    "$id": "/properties/ironic/properties/introspection_flag",
                    "description": "Flag to determine if introspection is needed",
                    "type": "boolean",
                    "default": true
                }
            }
        },
        "contrail_command_host": {
            "$id": "/properties/contrail_command_host",
            "type": "string"
        }
    }
}

{
    "type": "object",
    "definitions": {},
    "$schema": "http://json-schema.org/draft-06/schema#",
    "properties": {
        "fabric_uuid": {
            "$id": "/properties/input/properties/fabric_uuid",
            "format": "uuid",
            "type": "string",
            "title": "The Fabric_uuid Schema",
            "description": "UUID of the fabric object created",
            "default": "",
            "examples": [
                "123456789"
            ]
        },
        "device_count": {
            "$id": "/properties/input/properties/device_count",
            "type": "integer",
            "title": "The Device Count Schema",
            "description": "Number of devices to discover",
            "default": 0,
            "examples": [
                1,
                2,
                3,
                4,
                5
            ]
        }
    }
}

