{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "HTML Widget Template Schema",
    "description": "Defines a web-component based widget template that uses vanilla HTML.",
    "type": "object",
    "additionalProperties": false,
    "required": [
        "meta",
        "htmlTemplate"
    ],
    "properties": {
        "meta": {
            "type": "object",
            "title": "Template Meta",
            "additionalProperties": false,
            "required": [
                "dependencies",
                "plugins"
            ],
            "properties": {
                "dependencies": {
                    "type": "array",
                    "description": "A list of NPM resources to load into the widget",
                    "items": {
                        "$ref": "#/definitions/npmDependency"
                    }
                },
                "plugins": {
                    "type": "array",
                    "description": "A list of component editors used in editing the widget",
                    "items": {
                        "$ref": "#/definitions/npmDependency"
                    }
                }
            }
        },
        "htmlTemplate": {
            "type": "string",
            "title": "HTML Template",
            "description": "Raw HTML content that can use web components."
        }
    },
    "definitions": {
        "npmDependency": {
            "type": "object",
            "properties": {
                "package": {
                    "type": "string",
                    "description": "An NPM package name or scoped package"
                },
                "version": {
                    "type": "string",
                    "description": "An NPM version string, such as Patch releases: 1.0 or 1.0.x or ~1.0.4 Minor releases: 1 or 1.x or ^1.0.4 Major releases: * or x",
                    "default": "latest"
                },
                "filePath": {
                    "type": "string",
                    "description": "The path to a resource in the specified package",
                    "default": ""
                }
            },
            "required": [
                "version",
                "package"
            ]
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-06/schema#",
    "title": "Reward API Input",
    "description": "Defines the reward API data input structure.",
    "type": "object",
    "properties": {
        "type": {
            "type": "string",
            "title": "Reward Type",
            "enum": [
                "PCT_DISCOUNT",
                "FUELTANK",
                "CREDIT",
                "INTEGRATION"
            ]
        }
    },
    "dependencies": {
        "type": {
            "oneOf": [
                {
                    "properties": {
                        "type": {
                            "enum": [
                                "PCT_DISCOUNT"
                            ]
                        },
                        "discountPercent": {
                            "type": "integer",
                            "title": "Discount Percent",
                            "exclusiveMinimum": 0,
                            "maximum": 100,
                            "description": "The discount associated with this reward"
                        },
                        "name": {
                            "$ref": "#/definitions/rewardName"
                        },
                        "dateExpires": {
                            "$ref": "#/definitions/rewardDateExpires"
                        },
                        "cancellable": {
                            "$ref": "#/definitions/rewardCancellable"
                        },
                        "dateScheduledFor": {
                            "$ref": "#/definitions/rewardDateScheduledFor"
                        }
                    },
                    "additionalProperties": false,
                    "required": [
                        "type",
                        "discountPercent"
                    ]
                },
                {
                    "properties": {
                        "type": {
                            "enum": [
                                "FUELTANK"
                            ]
                        },
                        "fuelTankCode": {
                            "type": "string",
                            "title": "Fuel Tank Code",
                            "description": "The associated coupon code uploaded via the fuel tank API or portal code manager"
                        },
                        "unit": {
                            "$ref": "#/definitions/rewardUnit"
                        },
                        "amount": {
                            "type": "string",
                            "title": "Amount",
                            "description": "The amount of credit or discount to be given"
                        },
                        "dateExpires": {
                            "$ref": "#/definitions/rewardDateExpires"
                        },
                        "fuelTankType": {
                            "type": "string",
                            "title": "Fuel Tank Type",
                            "description": "The type of fuel tank reward being given",
                            "enum": [
                                "PCT_DISCOUNT",
                                "CREDIT"
                            ]
                        },
                        "cancellable": {
                            "$ref": "#/definitions/rewardCancellable"
                        }
                    },
                    "additionalProperties": false,
                    "required": [
                        "type",
                        "fuelTankCode",
                        "fuelTankType",
                        "amount"
                    ]
                },
                {
                    "properties": {
                        "type": {
                            "enum": [
                                "CREDIT"
                            ]
                        },
                        "unit": {
                            "$ref": "#/definitions/rewardUnit"
                        },
                        "name": {
                            "$ref": "#/definitions/rewardName"
                        },
                        "assignedCredit": {
                            "type": "integer",
                            "title": "Assigned Credit",
                            "exclusiveMinimum": 0,
                            "description": "The initial redeemable credit assigned to be assigned to reward"
                        },
                        "dateExpires": {
                            "$ref": "#/definitions/rewardDateExpires"
                        },
                        "cancellable": {
                            "$ref": "#/definitions/rewardCancellable"
                        },
                        "dateScheduledFor": {
                            "$ref": "#/definitions/rewardDateScheduledFor"
                        }
                    },
                    "additionalProperties": false,
                    "required": [
                        "type",
                        "unit",
                        "assignedCredit"
                    ]
                },
                {
                    "properties": {
                        "type": {
                            "enum": [
                                "INTEGRATION"
                            ]
                        },
                        "unit": {
                            "$ref": "#/definitions/rewardUnit"
                        },
                        "name": {
                            "$ref": "#/definitions/rewardName"
                        },
                        "description": {
                            "type": "string",
                            "title": "Reward Description",
                            "description": "This text describes the integration reward given in more detail"
                        },
                        "valueInCents": {
                            "type": "string",
                            "title": "Reward Amount",
                            "description": "The value in base currency unit (i.e. cents) to be assigned to this reward"
                        },
                        "integrationSettings": {
                            "$ref": "#/definitions/integrationSettings"
                        }
                    },
                    "additionalProperties": false,
                    "required": [
                        "type",
                        "unit",
                        "valueInCents",
                        "integrationSettings"
                    ]
                }
            ]
        }
    },
    "definitions": {
        "rewardUnit": {
            "type": "string",
            "title": "Unit",
            "description": "The unit of credit associated with this reward (i.e. months or usd)"
        },
        "rewardName": {
            "type": [
                "string",
                "null"
            ],
            "title": "Reward Name"
        },
        "rewardDateExpires": {
            "type": [
                "integer",
                "null"
            ],
            "title": "Reward Expiry Date",
            "description": "The date this reward will expire"
        },
        "rewardCancellable": {
            "type": [
                "boolean",
                "null"
            ],
            "title": "Cancellable",
            "description": "Whether this reward can be cancelled"
        },
        "rewardDateScheduledFor": {
            "type": [
                "integer",
                "null"
            ],
            "title": "Scheduled Reward Given Date",
            "description": "If the reward is created in a PENDING state this is the date we will attempt to 'give' it"
        },
        "integrationSettings": {
            "type": "object",
            "title": "Integration Settings",
            "properties": {
                "templateId": {
                    "type": "string",
                    "title": "Email Template ID"
                },
                "giftId": {
                    "type": "string"
                },
                "utid": {
                    "type": "string"
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-06/schema#",
    "title": "Unit Pretty Value Format Context",
    "description": "The context for rendering custom unit prettyValue",
    "type": "object",
    "properties": {
        "unit": {
            "type": "string",
            "title": "Unit",
            "description": "The unit of the reward",
            "minLength": 1
        },
        "value": {
            "type": "integer",
            "title": "Value",
            "description": "The value of the reward. If the reward is currency based, then this is the value in the currency's fractional unit."
        },
        "name": {
            "type": "string",
            "title": "Name",
            "description": "The name of the reward"
        },
        "currencySymbol": {
            "type": "string",
            "title": "Currency Symbol",
            "description": "The currency symbol in the rendering locale",
            "minLength": 1
        },
        "currencyLocalizedSymbol": {
            "type": "string",
            "title": "Currency Localized Symbol",
            "description": "The currency symbol in the currency's native locale",
            "minLength": 1
        },
        "currencyCode": {
            "type": "string",
